command:
set -o pipefail
cd "$(git rev-parse --show-toplevel)" && python -B -c "
import pickle, requests
r = requests.Response(); r._content=b'{\"bad\":}'; r.encoding='utf-8'; r.status_code=200
try:
    r.json()
except Exception as e:
    print(type(e), e.args)
    try:
        pickle.loads(pickle.dumps(e))
    except Exception as e2:
        print('PICKLE FAIL', type(e2), e2)
"
